#!/bin/bash -l
#SBATCH --job-name=fl_dir_grid
#SBATCH --output=logs/dirichlet_%A_%a.out
#SBATCH --error=logs/dirichlet_%A_%a.err
#SBATCH --array=0-14%3
#SBATCH --time=48:00:00
#SBATCH --cpus-per-task=4
#SBATCH --mem=32G
#SBATCH --gres=gpu:1

set -euo pipefail

# -----------------------------------------------------------------------------
# Full Dirichlet search matrix: 5 datasets x 3 heterogeneity cases = 15 jobs.
#
# Scenario indices are generated by run_dirichlet_search.py in this order:
#   0  CIFAR-10   highly non-IID   alpha=0.1
#   1  CIFAR-10   mildly non-IID   alpha=0.5
#   2  CIFAR-10   IID-like         alpha=100
#   3  CIFAR-100  highly non-IID   alpha=0.1
#   4  CIFAR-100  mildly non-IID   alpha=0.5
#   5  CIFAR-100  IID-like         alpha=100
#   6  Covtype    highly non-IID   alpha=0.1
#   7  Covtype    mildly non-IID   alpha=0.5
#   8  Covtype    IID-like         alpha=100
#   9  FEMNIST    highly non-IID   alpha=0.1
#  10  FEMNIST    mildly non-IID   alpha=0.5
#  11  FEMNIST    IID-like         alpha=100
#  12  Shakespeare highly non-IID  alpha=0.1
#  13  Shakespeare mildly non-IID  alpha=0.5
#  14  Shakespeare IID-like        alpha=100
#
# %3 limits the number of simultaneously running array jobs to three. Increase
# or reduce this value according to the cluster allocation available to you.
# -----------------------------------------------------------------------------

module purge
module load python/3.12.0/default
module load cuda/12.8/default

# Submit this script from the benchmark project directory.  PROJECT_DIR can be
# overridden explicitly with:
#   sbatch --export=ALL,PROJECT_DIR=/absolute/project/path cluster/submit_dirichlet_grid_array.sh
PROJECT_DIR="${PROJECT_DIR:-${SLURM_SUBMIT_DIR}}"
cd "${PROJECT_DIR}"

mkdir -p logs search_outputs partition_cache

printf '\n===== SLURM JOB INFORMATION =====\n'
echo "Job ID: ${SLURM_JOB_ID}"
echo "Array task ID: ${SLURM_ARRAY_TASK_ID}"
echo "Node: $(hostname)"
echo "Project directory: ${PROJECT_DIR}"
echo "Start time: $(date)"

printf '\n===== PYTHON / GPU CHECK =====\n'
echo "Python path:"
which python
python -V

echo "NVIDIA driver/GPU info:"
nvidia-smi || true

echo "Checking PyTorch/CUDA..."
python - <<'PY'
import sys
import torch

print("torch:", torch.__version__)
print("torch file:", torch.__file__)
print("torch CUDA build:", torch.version.cuda)
print("CUDA available:", torch.cuda.is_available())
if not torch.cuda.is_available():
    sys.exit(
        "ERROR: CUDA was requested, but PyTorch cannot use the GPU. "
        "Check the node driver, CUDA module, and PyTorch CUDA build."
    )
print("GPU:", torch.cuda.get_device_name(0))
PY

python -c "import torchvision; print('torchvision:', torchvision.__version__, 'file:', torchvision.__file__)"

printf '\n===== SELECTED SCENARIO =====\n'
python run_dirichlet_search.py --list | sed -n "$((SLURM_ARRAY_TASK_ID + 1))p"

printf '\n===== STARTING CONTROLLED SEARCH =====\n'
# Candidate and confirmation runs use convergence-based stopping.  The maximum
# round count in the YAML file is only a safety ceiling.
python run_dirichlet_search.py \
    --index "${SLURM_ARRAY_TASK_ID}" \
    --search-config configs/controlled_search_grid.yaml

printf '\n===== JOB COMPLETE =====\n'
echo "End time: $(date)"
